// Telegram Trigger → shape que espera "Auth + Normalize" (HPF Inbound Handler)
return $input.all().map(item => {
  const j = item.json || {};
  const msg = j.message || j;
  const chat = msg.chat || {};
  const from = msg.from || {};

  const chatId = String(chat.id ?? from.id ?? 'tg_unknown');

  let message_type = 'text';
  let message_text = msg.text || msg.caption || '';
  let media_url = '';
  let telegram_file_id = '';

  if (msg.voice || msg.audio) {
    message_type = 'audio';
    telegram_file_id = (msg.voice || msg.audio).file_id || '';
  } else if (Array.isArray(msg.photo) && msg.photo.length) {
    message_type = 'image';
    telegram_file_id = msg.photo[msg.photo.length - 1].file_id || '';
  } else if (!message_text) {
    // sticker / gif / documento / video / ubicacion / contacto: no los podemos leer,
    // pero NO deben tirar la ejecucion. El agente responde con naturalidad.
    message_type = 'text';
    message_text = '(el lead mando un sticker o archivo que no puedo abrir)';
  }

  return {
    json: {
      body: {
        contact_id: chatId,
        opportunity_id: `tg_opp_${chatId}`,
        phone: chatId,
        message_type,
        message_text,
        media_url,
        telegram_file_id,
        stage: 'Evento Identificado',
        custom_fields: {
          evento_detectado: '',
          imagen_input: false,
          productos_mostrados: '[]',
          cotizacion_emitida: false,
          monto_cotizado_mxn: 0,
          cp_entrega: '',
          had_information: false,
          had_image: false,
          had_quote: false,
          last_outbound_at: '',
        },
      },
      _telegram: {
        chat_id: chatId,
        first_name: from.first_name || '',
        last_name: from.last_name || '',
      },
    },
  };
});

// Auth la valida n8n en el nodo Webhook (credencial Header Auth). Aca solo normalizamos.
//
// PAYLOAD REAL DE GHL (WF-01, accion Webhook con CUSTOM DATA):
// GHL manda su "standard data" (contacto en root, location, message:{type,body,direction,status},
// workflow) MAS los pares de Custom Data mergeados en el root:
//   contact_id     = {{contact.id}}
//   opportunity_id = {{opportunity.id}}
//   phone          = {{contact.phone}}
//   stage          = {{opportunity.stage_name}}
//   message_type   = "text"                  <-- LITERAL hardcodeado en WF-01
//   message_text   = {{message.body}}
//   media_url      = {{message.attachments}} <-- ARRAY, GHL lo serializa
//
// Por eso NO confiamos en message_type: si hay media, el tipo real lo define el media.
const item = $input.first();
const b  = item.json?.body || item.body || item.json || {};
const m  = b.message || {};
const cd = b.customData || b.custom_data || {};

const pick = (...v) => { for (const x of v) if (x !== undefined && x !== null && x !== '') return x; return ''; };
const S = (v) => (v === undefined || v === null) ? '' : String(v);

// {{message.attachments}} puede llegar como array real, como '["url"]', como "a, b",
// o sin resolver ("[object Object]" / "{{...}}" / ""). Normalizamos a 1 URL o ''.
function firstUrl(v) {
  if (Array.isArray(v)) return S(v[0]);
  let s = S(v).trim();
  if (!s || s === '[object Object]' || s === 'null' || s === 'undefined' || s.startsWith('{{')) return '';
  if (s.startsWith('[')) {
    try { const arr = JSON.parse(s); if (Array.isArray(arr)) return S(arr[0]); } catch (e) {}
    s = s.replace(/^\[|\]$/g, '').replace(/["']/g, '');
  }
  return s.split(',')[0].trim();
}

const contact_id     = S(pick(b.contact_id, b.contactId, cd.contact_id, m.contactId));
const opportunity_id = S(pick(b.opportunity_id, b.opportunityId, cd.opportunity_id, b.id));
const phone          = S(pick(b.phone, b.phoneNumber, cd.phone, b.contact?.phone));
const message_text   = S(pick(b.message_text, b.messageText, m.body, m.text, cd.message_text, b.text));
const media_url      = firstUrl(pick(b.media_url, b.mediaUrl, b.attachments, m.attachments, m.media_url, cd.media_url));
const media_type     = S(pick(b.media_type, b.mediaType, m.media_type, m.contentType));

// TIPO: WF-01 manda 'text' fijo y message.type de GHL son CANALES (SMS/WhatsApp/IG/FB),
// no tipos de contenido -> si hay media, el media manda.
let message_type = S(pick(b.message_type, b.messageType, m.type)).toLowerCase();
if (media_url) {
  message_type = /\.(ogg|oga|mp3|m4a|wav|amr|mpeg)(\?|$)|audio|voice/i.test(media_type + ' ' + media_url)
    ? 'audio' : 'image';
} else if (!message_type || ['sms','whatsapp','ig','fb','live_chat','email','custom'].includes(message_type)) {
  message_type = 'text';
}
if (message_type === 'photo' || message_type === 'picture') message_type = 'image';
if (message_type === 'voice') message_type = 'audio';

const is_telegram_test = opportunity_id.startsWith('tg_opp_');
const channel = S(pick(b.channel, cd.channel, is_telegram_test ? 'telegram' : 'whatsapp'));

// Guardas: nunca dejar pasar un inbound sin identidad o vacio (mejor error visible que mensaje vacio al LLM)
const telegram_file_id = S(pick(b.telegram_file_id));  // Telegram: el media se resuelve mas adelante
const keys = Object.keys(b).join(', ') || '(body vacio)';
if (!contact_id) throw new Error(`Inbound sin contact_id. Keys recibidas: ${keys}`);
if (!message_text && !media_url && !telegram_file_id) {
  // Causa tipica: WF-01 se disparo como TEST o con un trigger que no es de mensaje,
  // entonces {{message.body}}/{{message.attachments}} resuelven vacio.
  const hasMsg = !!(b.message && Object.keys(b.message).length);
  throw new Error(
    `Inbound sin texto ni media (el agente recibiria un mensaje vacio). ` +
    (hasMsg ? `Llego objeto 'message' pero sin body/attachments. `
            : `NO llego objeto 'message': WF-01 se disparo sin contexto de mensaje ` +
              `(test manual o trigger que no es "Customer Replied"). `) +
    `Keys: ${keys}`
  );
}

return {
  contact_id, opportunity_id, phone, channel,
  message_type, message_text, media_url, media_type,
  telegram_file_id,
  stage: S(pick(b.stage, b.pipleline_stage, b.pipeline_stage, cd.stage)),
  custom_fields: b.custom_fields || b.customFields || {},
  is_telegram_test,
  raw: { ...b, channel },
};

