const response = $json.choices?.[0]?.message?.content || '{}';
const parsed = JSON.parse(response);
return {
  ...$('Auth + Normalize').first().json,
  vision_producto: parsed.producto || 'no_identificado',
  vision_confianza: parsed.confianza || 0,
  vision_payment_proof: parsed.payment_proof || false,
  vision_razon: parsed.razon || '',
  message_text: `[Imagen recibida: ${parsed.producto} (confianza ${parsed.confianza})]`
};

const currentStage = $('Auth + Normalize').first().json.stage;
const mediaUrl = $('Auth + Normalize').first().json.media_url;

const STAGE_IDS = {
  'Esperando Pago': '843a06f1-1214-4baa-a3a0-f197cb240b5d',
  'Pago Confirmado': '96d760e5-f290-456c-a117-57e61ce6c27d'
};

let nextStageId = null;
let mensaje = '';
let notifyOscar = false;
let comprobanteField = null;

if (currentStage === 'Cotizado') {
  nextStageId = STAGE_IDS['Esperando Pago'];
  mensaje = '¡Recibí tu comprobante! 🎉 Lo verificamos en breve y te confirmamos.';
  comprobanteField = 'anticipo';
} else if (currentStage === 'Esperando Pago') {
  nextStageId = STAGE_IDS['Pago Confirmado'];
  mensaje = '¡Pago confirmado! ✅ Ahora pasamos al diseño de tus recuerditos 🎨';
  notifyOscar = true;
  comprobanteField = 'liquidacion';
} else {
  mensaje = 'Comprobante recibido, un asesor te contactará pronto.';
}

return {
  ...$('Auth + Normalize').first().json,
  nextStageId,
  mensaje,
  notifyOscar,
  currentStage,
  comprobanteField,
  mediaUrl
};

const row = $json;
const messages = Array.isArray(row.pending_messages) ? row.pending_messages : JSON.parse(row.pending_messages || '[]');
const combinedText = messages.join('\n');

return {
  ...$('Auth + Normalize').first().json,
  message_text: combinedText
};

