const esCotiz = (t) => /x\s*\$/.test(t) && /^\s*\*?\s*Total\b/im.test(t);
function formatoCotiz(t) {
  const lineas = t.split('\n').map(l => {
    const c = l.replace(/\*/g, '');
    let m = c.match(/^(\s*\d+\s+)(.+?)(\s*x\s*\$[\d.,]+\s*=\s*)(\$[\d.,]+)\s*$/i);
    if (m) return m[1] + '*' + m[2].trim() + '*' + m[3] + '*' + m[4] + '*';
    m = c.match(/^\s*(Total|Anticipo)\b(.*)$/i);
    if (m) return '*' + (m[1] + m[2]).trim() + '*';
    return l;
  });
  const iProd = lineas.findIndex(l => /x\s*\$/.test(l));
  if (iProd !== -1 && !lineas.some(l => /7 DIAS DE PROMO/i.test(l))) {
    lineas.splice(iProd, 0, '⏳(7 DIAS DE PROMO)⏳');
  }
  return lineas.join('\n');
}

function partirOraciones(p) {
  const out = []; let cur = '';
  const toks = p.split(/(?<=[.!?…])\s+/);
  for (const t of toks) {
    cur = cur ? cur + ' ' + t : t;
    const sinCierre = /\d[.,]$/.test(cur) || ABREV.test(cur) || /https?:\/\/\S*$/.test(cur);
    if (!sinCierre && /[.!?…]$/.test(cur)) { out.push(cur); cur = ''; }
  }
  if (cur.trim()) out.push(cur);
  const res = [];
  for (const x of out.filter(y => y.trim())) {
    if (!/[a-záéíóúñü]/i.test(x) && res.length) res[res.length - 1] += ' ' + x.trim();
    else res.push(x);
  }
  return res;
}
let burbujas = [];
for (const b of bloquesFinal) {
  if (b.tipo !== 'libre') { burbujas.push({ text: b.text, atomica: true }); continue; }
  for (const parrafo of b.text.split(/\n{2,}/)) {
    const lineasP = parrafo.split('\n');
    const esLista = lineasP.length > 1 && lineasP.every(l => /^\s*[-*·•]|^\s*\d+[.)]\s/.test(l));
    if (esLista) { burbujas.push({ text: parrafo, atomica: false }); continue; }
    const sents = partirOraciones(parrafo.replace(/\n/g, ' '));
    if (sents.length <= 2) { burbujas.push({ text: sents.join(' ') || parrafo, atomica: false }); }
    else {
      const mitad = Math.ceil(sents.length / 2);
      burbujas.push({ text: sents.slice(0, mitad).join(' '), atomica: false });
      burbujas.push({ text: sents.slice(mitad).join(' '), atomica: false });
    }
  }
}
burbujas = burbujas.filter(b => b.text && b.text.trim());
while (burbujas.length > MAX_BURBUJAS) {
  let i = -1;
  for (let k = burbujas.length - 2; k >= 0; k--) if (!burbujas[k].atomica && !burbujas[k + 1].atomica) { i = k; break; }
  if (i === -1) break;
  burbujas[i].text = (burbujas[i].text + '\n' + burbujas[i + 1].text).trim();
  burbujas.splice(i + 1, 1);
}
for (const b of burbujas) {
  if (b.atomica) continue;
  b.text = b.text.replace(/(?<![.\d])\.$/, '');
}

let out = burbujas.map(b => ({ message_part: b.text, photo_url: '' }));

// Video de reseñas de confianza: va DESPUES de la cotizacion y ANTES de los 7
// pasos (pedido de Oscar, 13/8). Se ancla al mensaje de los 7 pasos, que sale
// una sola vez por conversacion, asi que el video tampoco se repite.
for (const p of out) {
  const t = S(p.message_part);
  if (esCotiz(t)) p.message_part = formatoCotiz(t);
}

// Los 7 pasos, garantizados por codigo. El modelo los omite de forma
// intermitente -sobre todo si el contexto trae cotizacion_emitida- y el
// pedido de Oscar es que salgan en la primera cotizacion de la conversacion.
// Mismo patron que SIETE_PASOS y formatoCotiz: el codigo no le pide al modelo
// que se acuerde, se lo impone. Dos señales para no repetirlos: el flag de la
// opportunity y el memo local.
const cotizoAntes = !!nodo('Mapear Custom Fields', ['custom_fields', 'cotizacion_emitida'], false);
const iCotiz = out.findIndex(p => esCotiz(S(p.message_part)));
if (iCotiz !== -1 && !out.some(p => RE_SIETE.test(S(p.message_part))) && !cotizoAntes && !memo.siete) {
  out.splice(iCotiz + 1, 0, { message_part: SIETE_PASOS, photo_url: '' });
}
if (iCotiz !== -1) memo.siete = true;

const iSiete = out.findIndex(p => RE_SIETE.test(S(p.message_part)));
if (iSiete !== -1) {
  out.splice(iSiete, 0,
    { message_part: '', photo_url: '', video_url: VIDEO_RESENAS },
    { message_part: TEXTO_RESENAS, photo_url: '' });
}
const fichasFinal = fichas.slice(0, MAX_FOTOS);
if (fichasFinal.length) {
  const msgs = [];
  for (const e of fichasFinal) {
    msgs.push({ message_part: fichaDe(e, evento), photo_url: e.u || '' });
    const videoUrl = videoDe(e);
    if (videoUrl) msgs.push({ message_part: 'Mira este video para que veas cómo se ve 🎥', photo_url: '', video_url: videoUrl });
    const catE = e.cat ? porId(e.cat) : null;
    if (catE) msgs.push({ message_part: catE.f, photo_url: catE.u });
    const pdfUrl = pdfDe(e, evento);
    if (pdfUrl) {
      const cap = (e.id === 'cuentas') ? '' : 'Aquí tienes el catálogo completo 📋';
      msgs.push({ message_part: cap, photo_url: '', doc_url: pdfUrl });
    }
  }
  const soloCuentas = fichasFinal.length === 1 && fichasFinal[0].id === 'cuentas';
  const insertar = (out.length && !soloCuentas) ? 1 : 0;
  out = out.slice(0, insertar).concat(msgs, out.slice(insertar));
  const principales = fichasFinal.filter(e => e.tipo === 'principal');
  if (principales.length) {
    const fem = principales.every(e => GRUPOS_FEMENINOS.indexOf(e.g) !== -1);
    out.push({ message_part: CTA_DATOS(fem), photo_url: '' });
  }
} else if (ctaYaEscrito) {
  out.push({ message_part: CTA_DATOS(false), photo_url: '' });
}

// La portada REEMPLAZA la respuesta del turno, no se le suma.
if (eventoReciente && !fichasFinal.length) {
  const ev = IMAGENES[evento] ? evento : 'OTROS';
  out = [{ message_part: PROMO, photo_url: '' }, { message_part: CAPTION_EVENTO[ev], photo_url: IMAGENES[ev] }];
}

// Link del mapa, garantizado por codigo. Oscar lo pidio explicito en la reunion
// del 11/8 ("la direccion es tal. Y mandarles el Google Maps"), pero el prompt
// lo tiene solo como dato suelto en [7] y el modelo lo incluye o no segun el
// turno. Si el bot mando la direccion y no puso el link, se agrega detras.
const RE_DIRECCION = /ZAVALA\s*#?\s*538|JUAN\s+R\.?\s*ZAVALA|d[oó]nde\s+estamos/i;
const iDir = out.findIndex(p => RE_DIRECCION.test(S(p.message_part)));
if (iDir !== -1) {
  out[iDir] = { message_part: MSG_UBICACION, photo_url: '' };
  if (iDir > 0 && /ubicados en Guadalajara|env[ií]os a todo M[eé]xico/i.test(S(out[iDir - 1].message_part))) out.splice(iDir - 1, 1);
  out = out.filter((p, i) => !(S(p.message_part).indexOf('goo.su') !== -1 && S(p.message_part) !== MSG_UBICACION));
}

if (!out.length) { const t = filtrarLibre(text); if (t) out = [{ message_part: t, photo_url: '' }]; }

memo.evento = evento || memo.evento;
if (eventoReciente) memo.header = true;
memo.grupos = Array.from(new Set([].concat(memo.grupos || [], fichasFinal.map(e => e.g))));
_sd.hpf[_cid] = memo;

const final = [];
for (const p of out) {
  const url = p.photo_url || ''; const doc = p.doc_url || ''; const vid = p.video_url || ''; const txt = S(p.message_part);
  if (url && txt.length > 1000) {
    let corte = txt.lastIndexOf(' ', 1000); if (corte < 500) corte = 1000;
    final.push({ message_part: txt.slice(0, corte), photo_url: url, doc_url: '', video_url: '' });
    final.push({ message_part: txt.slice(corte).trim(), photo_url: '', doc_url: doc, video_url: vid });
  } else final.push({ message_part: txt, photo_url: url, doc_url: doc, video_url: vid });
}
return final.filter(p => p.message_part || p.photo_url || p.doc_url || p.video_url);

const customFields = $json.opportunity?.customFields || [];
const EVENTO_FIELD_ID = 'ahVpF5ldsRcuOIn9Mxdk';
const eventoField = customFields.find(cf => cf.id === EVENTO_FIELD_ID);
const currentEvento = eventoField ? (Array.isArray(eventoField.fieldValue) ? eventoField.fieldValue[0] : eventoField.fieldValue) : '';

const incomingEvento = $('Auth + Normalize').first().json.custom_fields.evento_detectado || '';
const justSet = (!incomingEvento || incomingEvento === '') && currentEvento && currentEvento !== '';

const IMAGENES = {
