// Convierte el binario de Telegram en data URL (OpenAI Vision acepta base64).
// En producción (GHL) no hay binario y se conserva el media_url original.
const base = $('Combine Messages').first().json;
const item = $input.first();
let media_url = base.media_url || '';
try {
  if (item.binary && item.binary.data) {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    const mime = item.binary.data.mimeType || (base.message_type === 'audio' ? 'audio/ogg' : 'image/jpeg');
    media_url = `data:${mime};base64,${buf.toString('base64')}`;
  }
} catch (e) {}
return [{ json: { ...base, media_url }, binary: item.binary }];

// CALCULAR_ENVIO — calcula el costo de envío de un pedido HPF.
// Input: variable `query` (string) que pasa el agente = JSON [{producto, cantidad}].
// Output: string para el agente (costo de envío, o aviso de mínimo no alcanzado).
// Lógica portada de happyflops-calculadora-v2.json (pesos + límites de caja + brackets).

const WEIGHT_BY_PRODUCT = {
  "Mandiles": 0, "Kits Anticrudas": 0, "Costales": 0, "Bolsa": 0,
  "Cilindros": 0.14, "Vaso Popote 24 oz": 0.14, "Vasos Popote": 0.14,
  "Sandalias Delgadas": 0.15, "Sandalias Gruesas": 0.15, "Pantuflas": 0.15,
  "Pantuflas Mono": 0.15, "Pantufla Moño Satin": 0.15, "Pantufla Moño Peluche": 0.15
};
const CATEGORY_BY_PRODUCT = {
  "Cilindros": "CILINDROS", "Vaso Popote 24 oz": "CILINDROS", "Vasos Popote": "CILINDROS",
  "Sandalias Delgadas": "SANDALIAS", "Sandalias Gruesas": "SANDALIAS", "Pantuflas": "SANDALIAS",
  "Pantuflas Mono": "SANDALIAS", "Pantufla Moño Satin": "SANDALIAS", "Pantufla Moño Peluche": "SANDALIAS",
  "Mandiles": "OTROS_0KG", "Kits Anticrudas": "OTROS_0KG", "Costales": "OTROS_0KG", "Bolsa": "OTROS_0KG"
};
const MIN_BY_PRODUCT = {
  "Sandalias Delgadas": 50, "Sandalias Gruesas": 50, "Pantuflas": 50, "Pantuflas Mono": 50,
  "Pantufla Moño Satin": 50, "Pantufla Moño Peluche": 50, "Cilindros": 40,
  "Vaso Popote 24 oz": 50, "Vasos Popote": 50, "Kits Anticrudas": 35, "Costales": 35, "Mandiles": 12
};
const PRODUCT_ALIASES = {
  "mandil": "Mandiles", "mandiles": "Mandiles",
  "kit anticruda": "Kits Anticrudas", "kits anticruda": "Kits Anticrudas",
  "kit anticrudas": "Kits Anticrudas", "kits anticrudas": "Kits Anticrudas",
  "costal": "Costales", "costales": "Costales",
  "cilindro": "Cilindros", "cilindros": "Cilindros",
  "sandalia delgada": "Sandalias Delgadas", "sandalias delgadas": "Sandalias Delgadas",
  "sandalia gruesa": "Sandalias Gruesas", "sandalias gruesas": "Sandalias Gruesas",
  "sandalia": "Sandalias Delgadas", "sandalias": "Sandalias Delgadas",
  "pantufla": "Pantuflas", "pantuflas": "Pantuflas",
  "pantufla mono": "Pantuflas Mono", "pantuflas mono": "Pantuflas Mono",
  "pantufla mono satin": "Pantufla Moño Satin", "pantuflas mono satin": "Pantufla Moño Satin",
  "pantufla moño satin": "Pantufla Moño Satin", "pantuflas moño satin": "Pantufla Moño Satin",
  "pantufla moño satín": "Pantufla Moño Satin", "pantuflas moño satín": "Pantufla Moño Satin",
  "pantufla mono peluche": "Pantufla Moño Peluche", "pantuflas mono peluche": "Pantufla Moño Peluche",
  "pantufla moño peluche": "Pantufla Moño Peluche", "pantuflas moño peluche": "Pantufla Moño Peluche",
  "vaso popote": "Vaso Popote 24 oz", "vasos popote": "Vaso Popote 24 oz",
  "vaso popote 24 oz": "Vaso Popote 24 oz", "vasos popote 24 oz": "Vaso Popote 24 oz"
};
const LIMITS = {
  MAX_PER_BOX_WEIGHT_KG: 35, MAX_CILINDROS_PER_BOX: 250,
  MAX_SANDALIAS_PER_BOX: 200, MAX_COMBINED_SANDALIAS_CILINDROS_PER_BOX: 200
};

function costoPorPeso(pesoKg) {
  const p = Number(pesoKg.toFixed(2));
  if (p >= 0 && p <= 4.99) return 250;
  if (p >= 5 && p <= 7) return 280;
  if (p > 7 && p <= 12) return 300;
  if (p > 12 && p <= 19.99) return 350;
  if (p >= 19.99 && p <= 35) return 400;
  return 400;
}
function normalizeText(str) {
  return String(str || "").normalize("NFD").replace(/[̀-ͯ]/g, "")
    .toLowerCase().replace(/\s+/g, " ").trim();
}
function canon(raw) {
  const clean = normalizeText(raw);
  if (PRODUCT_ALIASES[clean]) return PRODUCT_ALIASES[clean];
  // Fallback por keyword: tolera las grafías del catálogo del prompt
  // ("Cilindros 500ml", "Vasos popote 24oz", "Sandalias delgadas (suela 9mm)", etc.).
  // Para envío solo importan peso + categoría; igual conservamos la variante si el texto la indica.
  if (clean.includes("cilindro")) return "Cilindros";
  if (clean.includes("vaso")) return "Vaso Popote 24 oz";
  if (clean.includes("mandil")) return "Mandiles";
  if (clean.includes("costal")) return "Costales";
  if (clean.includes("kit") && clean.includes("anticrud")) return "Kits Anticrudas";
  if (clean.includes("bolsa")) return "Bolsa";
  if (clean.includes("pantufla")) {
    if (clean.includes("peluche")) return "Pantufla Moño Peluche";
    if (clean.includes("moño") || clean.includes("mono")) return "Pantufla Moño Satin";
    return "Pantuflas";
  }
  if (clean.includes("sandalia")) {
    if (clean.includes("gruesa") || clean.includes("15mm")) return "Sandalias Gruesas";
    return "Sandalias Delgadas";
  }
  return String(raw || "").trim();
}
function cloneEmptyBoxState() { return { peso: 0, cil: 0, sand: 0, combSC: 0, contenido: {} }; }
function addToBox(box, product, qty, w) {
  box.contenido[product] = (box.contenido[product] || 0) + qty;
  box.peso += qty * w;
  const cat = CATEGORY_BY_PRODUCT[product] || "OTROS";
  if (cat === "CILINDROS") { box.cil += qty; box.combSC += qty; }
  else if (cat === "SANDALIAS") { box.sand += qty; box.combSC += qty; }
}
function capacityForProductInBox(box, product, w) {
  const cat = CATEGORY_BY_PRODUCT[product] || "OTROS";
  let cap = Infinity;
  if (w > 0) cap = Math.min(cap, Math.max(0, Math.floor((LIMITS.MAX_PER_BOX_WEIGHT_KG - box.peso) / w)));
  if (cat === "CILINDROS") {
    cap = Math.min(cap, LIMITS.MAX_CILINDROS_PER_BOX - box.cil);
    cap = Math.min(cap, LIMITS.MAX_COMBINED_SANDALIAS_CILINDROS_PER_BOX - box.combSC);
  } else if (cat === "SANDALIAS") {
    cap = Math.min(cap, LIMITS.MAX_SANDALIAS_PER_BOX - box.sand);
    cap = Math.min(cap, LIMITS.MAX_COMBINED_SANDALIAS_CILINDROS_PER_BOX - box.combSC);
  } else if (cat === "OTROS_0KG") { cap = Infinity; }
  return Math.max(0, cap);
}
function packBoxes(lines) {
  const boxes = [];
  let cur = cloneEmptyBoxState();
  const remaining = {};
  lines.forEach(ln => { remaining[ln.product] = (remaining[ln.product] || 0) + ln.quantity; });
  const hasRemaining = () => Object.keys(remaining).some(k => remaining[k] > 0);
  while (hasRemaining()) {
    let packed = false;
    for (const ln of lines) {
      const need = remaining[ln.product];
      if (!need) continue;
      const cap = capacityForProductInBox(cur, ln.product, ln.weight);
      if (cap <= 0) continue;
      const put = Math.min(need, cap);
      if (put > 0) { addToBox(cur, ln.product, put, ln.weight); remaining[ln.product] -= put; packed = true; }
    }
    if (!packed || !hasRemaining()) {
      if (Object.keys(cur.contenido).length > 0) boxes.push(cur);
      if (hasRemaining()) cur = cloneEmptyBoxState();
    }
  }
  return boxes;
}
function orderFromItems(arr) {
  const acc = {};
  const unknown = [];
  for (const row of arr) {
    const rawProd = String((row && (row.producto ?? row.product)) || "").trim();
    const qty = Number((row && (row.cantidad ?? row.qty)) || 0);
    if (!rawProd || !qty) continue;
    const prod = canon(rawProd);
    const w = WEIGHT_BY_PRODUCT[prod];
    if (typeof w !== "number") { unknown.push(rawProd); continue; }
    if (!acc[prod]) acc[prod] = { product: prod, quantity: 0, weight: w };
    acc[prod].quantity += qty;
  }
  return { lines: Object.values(acc), unknown };
}

// ---- parse input ----
let raw = (typeof query !== "undefined" && query != null) ? query : "";
if (typeof raw === "object") { try { raw = JSON.stringify(raw); } catch (e) { raw = ""; } }
let parsed = null;
try {
  const p = JSON.parse(raw);
  if (Array.isArray(p)) parsed = p;
  else if (p && Array.isArray(p.items)) parsed = p.items;
  else if (p && !Array.isArray(p) && (p.producto || p.product)) parsed = [p]; // objeto único
} catch (e) {}
if (!parsed) {
  parsed = [];
  String(raw).split(/[,;\n]/).forEach(seg => {
    seg = seg.trim(); if (!seg) return;
    let m = seg.match(/^(.+?):\s*(\d+)\s*$/);
    if (m) { parsed.push({ producto: m[1].trim(), cantidad: Number(m[2]) }); return; }
    m = seg.match(/^(\d+)\s+(.+)$/);
    if (m) { parsed.push({ producto: m[2].trim(), cantidad: Number(m[1]) }); return; }
  });
}
if (!parsed || !parsed.length) {
  return 'No pude leer los productos. Pasá un JSON como [{"producto":"Sandalias Delgadas","cantidad":100},{"producto":"Cilindros","cantidad":50}].';
}

const { lines, unknown } = orderFromItems(parsed);
if (!lines.length) {
  return 'No reconocí ningún producto válido' + (unknown.length ? ' (desconocidos: ' + unknown.join(", ") + ')' : '') + '. Usá los nombres exactos del catálogo.';
}

// minimums (defense in depth — el agente ya debería validar antes)
const viol = lines.filter(l => typeof MIN_BY_PRODUCT[l.product] === "number" && l.quantity < MIN_BY_PRODUCT[l.product])
  .map(l => l.product + ": pediste " + l.quantity + " (mínimo " + MIN_BY_PRODUCT[l.product] + ")");
if (viol.length) {
  return "MÍNIMO NO ALCANZADO: " + viol.join("; ") + ". Decile al cliente el mínimo real de cada producto y NO cotices hasta que ajuste la cantidad. No calcules envío ni fuerces un cálculo alternativo.";
}

const boxes = packBoxes(lines);
let total = 0;
boxes.forEach(b => { total += costoPorPeso(Number(b.peso.toFixed(2))); });

// NO mencionar nº de cajas ni peso (Regla 2 del prompt: nunca menciones cajas/kg).
return "Costo de envío: $" + total + ". IMPORTANTE: usá $" + total +
  " tal cual en la línea 'Envío:', sumalo a la suma de productos para el Total, y el Anticipo es 50% de ese Total con envío.";

const prev = $('Auth + Normalize').first().json;

// Si es un test de Telegram, no tocar el opportunity_id/stage sinteticos
if (prev.is_telegram_test) {
  return prev;
}

const STAGE_NAMES = {
